import React, { useState } from 'react';

const ContactForm = () => {
  // 1. Form-ல் டைப் செய்யும் டேட்டாவை சேமிக்க State உருவாக்குகிறோம்
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    service: '',
    message: ''
  });
  const [status, setStatus] = useState('');

  // 2. யூசர் டைப் செய்யும்போது டேட்டாவை அப்டேட் செய்வது
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // 3. Submit பட்டனை அழுத்தியதும் Python Backend-க்கு அனுப்புவது
  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus('Sending securely to Python Server...');

    try {
      // Python FastAPI இயங்கும் localhost:8000-க்கு டேட்டாவை அனுப்புகிறோம்
      const response = await fetch('http://localhost:8000/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        setStatus('✅ Message Sent Successfully!');
        // ஃபார்மை க்ளியர் செய்கிறோம்
        setFormData({ name: '', phone: '', service: '', message: '' });
      } else {
        setStatus('❌ Failed to send message.');
      }
    } catch (error) {
      console.error("API Error:", error);
      setStatus('❌ Error: Make sure Python Backend is running!');
    }
  };

  return (
    <section className="contact-section" id="contact">
      <div className="section-title">
        <h2>Get In Touch</h2>
        <p>Ready to bring your printing ideas to life? Contact us today!</p>
      </div>

      <div className="contact-grid">
        {/* Contact Form Box */}
        <div className="card">
          <h3>Send us a message</h3>
          <form onSubmit={handleSubmit}>
            <div className="input-wrapper">
              <input type="text" id="msg-name" name="name" required placeholder=" " value={formData.name} onChange={handleChange} />
              <label htmlFor="msg-name">Your Name</label>
              <i className="fa-solid fa-user input-icon"></i>
            </div>

            <div className="input-wrapper">
              <input type="tel" id="msg-phone" name="phone" required placeholder=" " value={formData.phone} onChange={handleChange} />
              <label htmlFor="msg-phone">Your Phone Number</label>
              <i className="fa-solid fa-phone input-icon"></i>
            </div>

            <div className="input-wrapper">
              <select id="msg-service" name="service" required value={formData.service} onChange={handleChange}>
                <option value="" disabled hidden></option>
                <option value="Calendar Printing">Calendar Printing</option>
                <option value="Business Cards">Business Cards</option>
                <option value="Brochures & Flyers">Brochures & Flyers</option>
                <option value="Wedding Cards">Wedding Cards</option>
                <option value="Banners & Posters">Banners & Posters</option>
                <option value="Custom Printing">Custom Printing</option>
              </select>
              <label htmlFor="msg-service">Select Service</label>
              <i className="fa-solid fa-tags input-icon"></i>
            </div>

            <div className="input-wrapper">
              <textarea id="msg-content" name="message" required placeholder=" " value={formData.message} onChange={handleChange}></textarea>
              <label htmlFor="msg-content">Your Message</label>
              <i className="fa-solid fa-comment-dots input-icon"></i>
            </div>

            <button type="submit" className="whatsapp-btn" style={{ background: 'var(--primary)' }}>
              <i className="fa-solid fa-paper-plane"></i> Send to Python Backend
            </button>

            {/* Status Message Display */}
            {status && <p style={{ marginTop: '15px', textAlign: 'center', fontWeight: 'bold', color: 'var(--primary)' }}>{status}</p>}
          </form>
        </div>

        {/* Business Info Box */}
        <div className="card info-card">
          <h3>Business Details</h3>
          <ul className="info-list" style={{ marginBottom: '25px' }}>
            <li>
              <i className="fa-solid fa-building"></i>
              <div>
                <strong>Karpagam Traders</strong>
                <span>Sivakasi's premium print house. Delivering outstanding calendar, corporate stationery, and customized prints.</span>
              </div>
            </li>
            <li>
              <i className="fa-solid fa-clock"></i>
              <div>
                <strong>Business Hours</strong>
                <span>Monday - Saturday: 9:00 AM - 8:00 PM<br/>Sunday: 10:00 AM - 6:00 PM</span>
              </div>
            </li>
            <li>
              <i className="fa-solid fa-map-location-dot"></i>
              <div>
                <strong>Map Directions</strong>
                <span>Sn Puram Road, Thiruthangal, Sivakasi, Tamil Nadu, 626130</span>
              </div>
            </li>
          </ul>
        </div>
      </div>
    </section>
  );
};

export default ContactForm;
